			// Types for mapping element
			ENTITYPE = 0
			COLTYPE = 5
			TABLETYPE = 4
			ATTRTYPE = 1
			RELATYPE = 3 //(source ent, targ ent)
			FKTYPE = 8
			INHERITTYPE = 9
