			LOGARCTYPE = 14
			var g_containerMappings = {}
			var g_attrMappings = {}

			var PLAINMESSAGE = 1;
			var ERRORMESSAGE = 0;
			var WARNINGMESSAGE = 2;
			var QUESTIONMESSAGE = 3;
			function fullmessage(msg, type) {
				Java.type("javax.swing.JOptionPane").showMessageDialog(null, msg, 'ODM-Translation', type);
			}

			function error(msg) {
				fullmessage(msg, ERRORMESSAGE);
			}

			function message(msg) {
				fullmessage(msg, PLAINMESSAGE);
			}

			function linemessage() {
				str = ''
				for (i=0;i<arguments.length;i++){
					str = str.concat(arguments[i],'\n')
				}
				message(str)
			}

			// simulates the not existing array.forEach method
			// for each element in arr, calls f(elem,idx)
			function forEach(arr,f){
				for (var idx = 0;idx < arr.length; idx++) { 
					f(arr[idx],idx);
				}
			}

			function getAllMappings(rmodels) {
				g_containerMappings = {}
				g_attrMappings = {}
				if (rmodels == null) return
				for (imod = 0; imod < rmodels.length; imod++) {
					rmod = rmodels[imod]
					modname = rmod.getName()
					tables = rmod.getTableSet()
					modelMap = rmod.getRMExtendedMap().getContainerMappings().toArray();
					if (modelMap != null) {
						for (imgm = 0; imgm < modelMap.length; imgm++) {
							logMap = modelMap[imgm]
							relName = tables.getObjectByID(logMap.getRelID())
							switch (logMap.getLogType()) {
								case ENTITYPE:
									logName = g_entitySet.getObjectByID(logMap.getLogID())
									break
								case RELATYPE:
									logName = g_relationSet.getObjectByID(logMap.getLogID())
									break;
								case INHERITTYPE:
									logName = g_inheritanceSet.getObjectByID(logMap.getLogID())
									break;
								default:
									logName = null
							}

							g_containerMappings[logMap.getID()] = {
								modelName: modname,
								logID: logMap.getLogID(),
								logName: logName,
								logType: logMap.getLogType(),
								relID: logMap.getRelID(),
								tableName: relName,
								relType: logMap.getRelType(),
								srcEntityID: logMap.getRealSourceEntityID(),
								trgEntityID: logMap.getRealTargetEntityID()
							}

							containedMaps = logMap.getContainedMappings()
							for (icm = 0; icm < containedMaps.length; icm++) {
								cm = containedMaps[icm]
								g_attrMappings[cm.getID()] = {
									modelName: modname,
									parentID: logMap.getID(),
									logID: cm.getLogID(),
									logType: cm.getLogType(),
									relID: cm.getRelID(),
									relType: cm.getRelType()
								}
							}
						}
					}
				}
			}

			function trimapo(s) {
				return s.replace(/^"|"$/g, '');
			}

			function curDateStr() {
				var currentdate = new Date();
				return currentdate.getDate() +
					"/" + (currentdate.getMonth() + 1) +
					"/" + currentdate.getFullYear() + "  " +
					currentdate.getHours() + ":" +
					currentdate.getMinutes() + ":" + currentdate.getSeconds();
			}

			function getContainerMaps(tabID) {
				maps = []
				for (key in g_containerMappings) {
					if (tabID == g_containerMappings[key].relID) maps.push(g_containerMappings[key])
				}
				return maps
			}

			function getContainerMap(entiID, tabID) {
				for (key in g_containerMappings) {
					if (tabID == g_containerMappings[key].relID && entiID == g_containerMappings[key].logID) return g_containerMappings[key]
				}
				return null
			}

			function getLogMap(logID, modName) {
				maps = []
				for (key in g_containerMappings) {
					if ((logID == g_containerMappings[key].logID) &&
						(modName == g_containerMappings[key].modelName)) maps.push(g_containerMappings[key])
				}
				return maps
			}

			function getColMaps(colID) {
				colsmap = []
				for (key in g_attrMappings) {
					//message(colID+'|'+cmap[icolmap].getRelID())
					if (colID == g_attrMappings[key].relID) colsmap.push(g_attrMappings[key])
				}
				return colsmap
			}

			function getColMap(colID, attrID) {
				for (key in g_attrMappings) {
					if (g_attrMappings[key].modelName == "--debug--") {
						message(key + '\n' + colID + '\n' + attrID + '\n' + g_attrMappings[key].relID + '\n' + g_attrMappings[key].logID)
					}
					if (colID == g_attrMappings[key].relID && attrID == g_attrMappings[key].logID) return g_attrMappings[key]
				}
				return null
			}

			function getAttrMap(attrID, modName) {
				attrmaps = []
				for (key in g_attrMappings) {
					//message(colID+'|'+cmap[icolmap].getRelID())
					if ((attrID == g_attrMappings[key].logID) &&
						(modName == g_attrMappings[key].modelName)) attrmaps.push(g_attrMappings[key])
				}
				return attrmaps
			}


			function getRelationAttribute(attrCollection, attrName) {
				for (grakey in attrCollection) {
					if (attrCollection[grakey].getName() == attrName) return attrCollection[grakey]
				}
				return null
			}

			function getRelationAttrByID(attrCollection, attrID) {
				for (grakey in attrCollection) {
					if (attrCollection[grakey].getObjectID() == attrID) return attrCollection[grakey]
				}
				return null
			}


			function do1line(values) {
				modelMapping = rmodel.getRMExtendedMap().getContainerMappings().toArray();
				tabName = values[0];
				colName = values[1];
				elemName = values[2];
				attrName = values[3];
				//linemessage(elemName,attrName,tabName,colName)
				relation = null
				entity = g_entitySet.getByName(elemName);
				if (entity != null) {
					attribute = entity.getElementByName(attrName);
				} else { // assume Relation 
					relation = g_relationSet.getByName(elemName)
					if (relation != null) {
						attribute = getRelationAttribute(relation.getAttributesCollection(), attrName);
					}
				}
				table = rmodel.getTableSet().getByName(tabName);
				// Neue Tabellen werden erzeugt
				if ((table == null) && (tabName != "")) {
					rmodel.createTable(tabName);
					table = rmodel.getTableSet().getByName(tabName);
					table.setComment("Created on " + curDateStr() + " during import from " + imppath)
					g_tabanz++
				}
				if (table != null) {
					column = table.getElementByName(colName);
				} else {
					column = null
				}
				// neue Columns werden erzeugt
				if ((column == null) && (colName != "")) {
					//linemessage('neue Column',colName,tabName)
					table.createColumn(colName)
					column = table.getElementByName(colName);
					column.setComment("Created on " + curDateStr() + " during import from " + imppath)
					g_colanz++
				}
				if ((entity != null) && (table != null)) {
					mapped = getContainerMap(entity.getObjectID(), table.getObjectID())
					if (mapped == null) {
						rmodel.getRMExtendedMap().createMapping(entity, table);
						g_tabmapanz++
					}
					if ((attribute != null) && (column != null)) {
						mapped = getColMap(column.getObjectID(), attribute.getObjectID())

						if (mapped == null) {
							rmodel.getRMExtendedMap().createMapping(attribute, column);
							g_colmapanz++
						}
					}
				}
				if ((relation != null) && (table != null)) {
					mapped = getContainerMap(relation.getObjectID(), table.getObjectID())
					if (mapped == null) {
						rmodel.getRMExtendedMap().createMapping(relation, table);
						g_tabmapanz++
					}
					if ((attribute != null) && (column != null)) {
						mapped = getColMap(column.getObjectID(), attribute.getObjectID())
						if (mapped == null) {
							rmodel.getRMExtendedMap().createMapping(attribute, column);
							g_colmapanz++
						}
					}
				}
			}

			function importFile(fpath) {
				var Paths = Java.type('java.nio.file.Paths');
				var Files = Java.type('java.nio.file.Files');
				var lines = Files.readAllLines(Paths.get(fpath), Java.type('java.nio.charset.StandardCharsets').UTF_8);
				for (lnoif = 0; lnoif < lines.length; lnoif++) {
					line = lines[lnoif]
					values = line.split(";");
					for (iif = 0; iif < values.length; iif++) {
						values[iif] = trimapo(values[iif]);
					}
					if (lnoif == 0) {
						var relModel = values[0];
						// falls 1. Zeichen von Excel stammt, schneide es ab
						if (relModel.match(/^[^A-Za-z]/)) {relModel = relModel.substring(1)}
						rmodel = model.getDesign().getRelationalDesigns().getByName(relModel);
						if (rmodel == null) {
							throw new Error("\nRelational model '" + relModel + "' does not exist.\n");
						}
						getAllMappings([rmodel])
					} else
					if (lnoif == 1) {
						// skip headers
						//message(lnoif+': '+"headers= "+values);
					} else {
						//linemessage(lnoif,values.length,values);
						if (values.length>=4){
							do1line(values);
							g_lineanz++
						}
					}
				};
			}

